    public static partial class Loc
    {
        static partial void ExtendLore(Dictionary<string, string> d)
        {
            d["lore.agent_d.age"] = "26 ans";
            d["lore.agent_d.sex"] = "Homme";
            d["lore.agent_d.origin"] = "New York, États-Unis";
            d["lore.agent_d.supernova"] = "À New York le soir de la Supernova, il dessine dans son atelier et voit une esquisse de son carnet prendre une ombre physique sur la table.";
            d["lore.agent_d.story"] = "Illustrateur de rue, il vend ses dessins dans le quartier de Harlem. Deux ans après la Supernova, un gang abat son ami d'enfance sous ses yeux. Dans la rage et le désespoir, il trace à la craie sur le trottoir une barrière, et elle se matérialise à l'instant où les balles frappent. Ce qu'il imagine devient réel.";
            d["lore.agent_d.look"] = "Jeune homme d'une vingtaine d'années, cheveux châtain clair mi-longs et ondulés, lunettes de vue à monture métallique rectangulaire, barbe courte et fine moustache, sourire en coin. Tenue : t-shirt lavande sous une veste de héros gris-violet aux plaques facettées, avec le symbole doré de The Dawn sur la poitrine.";
            d["lore.agent_d.power"] = "Matérialise ce que son esprit image : objets, structures, créatures temporaires. La solidité et la durée dépendent de la netteté de sa concentration.";
            d["lore.agent_m.age"] = "24 ans";
            d["lore.agent_m.sex"] = "Femme";
            d["lore.agent_m.origin"] = "Moscou, Russie";
            d["lore.agent_m.supernova"] = "À Moscou le soir de la Supernova, elle voit un instant la rue dans l'état où elle sera deux jours plus tard, avec des voitures renversées et des fenêtres brisées.";
            d["lore.agent_m.story"] = "Étudiante en histoire de l'art, elle restaure des fresques dans les églises de Moscou. Deux ans après la Supernova, un attentat frappe la cathédrale où elle travaille. Son frère, présent avec elle, est grièvement blessé sous ses yeux. Dans le choc, elle voit ce qui s'est passé juste avant, ce qui se passe maintenant et ce qui va arriver. Le passé, le présent et le futur de ce qui l'entoure deviennent visibles.";
            d["lore.agent_m.look"] = "Longs cheveux blond platine ondulés jusqu'aux épaules, petites boucles d'oreilles dorées, lunettes à monture fine géométrique dorée, trait d'eye-liner net. Tenue : manteau court cognac en cuir souple sur un haut en dentelle noire, avec le symbole doré de The Dawn sur l'épaule. Les verres de ses lunettes s'illuminent quand elle voit une vision.";
            d["lore.agent_m.power"] = "Perçoit le passé, le présent et le futur de ce qui l'entoure. Les visions sont fragmentées, et plus elles portent loin dans le temps, plus elles sont floues.";
            d["lore.ilona_varga.age"] = "27 ans";
            d["lore.ilona_varga.sex"] = "Femme";
            d["lore.ilona_varga.origin"] = "Budapest, Hongrie → Paris";
            d["lore.ilona_varga.supernova"] = "Le soir de la Supernova, elle est à Budapest. Elle sent un poids étrange dans sa poitrine, puis le silence.";
            d["lore.ilona_varga.story"] = "Fille d'un psychiatre, elle apprend très tôt à lire les émotions des autres. Deux ans après la Supernova, elle arrive à Paris, où une prise d'otages éclate dans une école. Un tireur la menace, et elle sent sa terreur se mettre à prendre forme : une silhouette noire surgit du sol. Le tireur s'effondre. C'est là que la peur d'autrui devient réelle.";
            d["lore.ilona_varga.look"] = "Silhouette fine, cheveux noirs tressés, regard gris. Tenue en tissu sombre aux bords déchirés et volutes d'ombre, avec un masque argenté.";
            d["lore.ilona_varga.power"] = "Donne une forme physique et tangible aux peurs de ses cibles.";
            d["lore.louis_dubois.age"] = "29 ans";
            d["lore.louis_dubois.sex"] = "Homme";
            d["lore.louis_dubois.origin"] = "Lyon, France → Paris";
            d["lore.louis_dubois.supernova"] = "Dans son laboratoire lyonnais le soir de la Supernova, les instruments s'affolent sans explication.";
            d["lore.louis_dubois.story"] = "Ingénieur électronicien dans un laboratoire de recherche, il ne retient des premiers mois qu'une fatigue persistante. Deux ans après la Supernova, un accident de particules le laisse traversé par des champs magnétiques. Pendant une évacuation à Paris, un incendie bloque une porte, et il est pris de panique. Il attire vers lui des chariots métalliques pour la bloquer. Le laboratoire parle d'accident ; pour lui, c'est un choix.";
            d["lore.louis_dubois.look"] = "Silhouette élancée, lunettes à monture fine, cheveux en bataille. Tenue gris acier avec des lignes de cuivre luminescentes et une ceinture aimantée.";
            d["lore.louis_dubois.power"] = "Crée et contrôle des champs magnétiques, attire ou repousse le métal et les objets chargés.";
            d["lore.ada_okonkwo.age"] = "33 ans";
            d["lore.ada_okonkwo.sex"] = "Femme";
            d["lore.ada_okonkwo.origin"] = "Lagos, Nigeria → Paris";
            d["lore.ada_okonkwo.supernova"] = "Au laboratoire à Lagos le soir de la Supernova, elle découvre une séquence ADN qu'elle ne reconnaît pas sur ses propres échantillons.";
            d["lore.ada_okonkwo.story"] = "Généticienne, elle travaille sur des traitements contre une maladie rare qui a tué son frère. Deux ans après la Supernova, une expérience échoue et l'ADN de son propre corps se réécrit. Pendant une évacuation à Paris, elle voit un enfant gravement blessé et, dans la panique, guérit ses blessures. Elle découvre aussi qu'elle peut altérer le vivant.";
            d["lore.ada_okonkwo.look"] = "Cheveux naturels coupés court, lunettes de laboratoire. Tenue médicale épurée blanche aux motifs de double hélice vert pâle, avec des veines lumineuses sous la peau aux poignets.";
            d["lore.ada_okonkwo.power"] = "Manipule l'ADN des êtres vivants : soigner, muter, accélérer ou ralentir des processus biologiques.";
            d["lore.victor_sorel.age"] = "48 ans";
            d["lore.victor_sorel.sex"] = "Homme";
            d["lore.victor_sorel.origin"] = "Bordeaux, France → Paris";
            d["lore.victor_sorel.supernova"] = "À Bordeaux le soir de la Supernova, il ressent une migraine violente qu'il met sur le compte du surmenage.";
            d["lore.victor_sorel.story"] = "Avocat brillant, il manipule ses clients et ses adversaires sans le savoir. Un an après la Supernova, il perd sa fille dans une affaire judiciaire qu'il a lui-même gagnée. Dans sa colère, un juge fait un geste à sa demande. Il se croit d'abord en plein délire. Quand il réalise que son pouvoir peut aussi faire le mal, il décide de le mettre au service de The Dawn.";
            d["lore.victor_sorel.look"] = "Costume trois-pièces sombre impeccable, cheveux poivre et sel, regard froid. Tenue de héros noire et or, sobre et élégante, avec un monocle à lentille.";
            d["lore.victor_sorel.power"] = "Prend le contrôle de l'esprit de ses cibles pour un temps limité.";
            d["lore.fatou_diallo.age"] = "28 ans";
            d["lore.fatou_diallo.sex"] = "Femme";
            d["lore.fatou_diallo.origin"] = "Dakar, Sénégal → Paris";
            d["lore.fatou_diallo.supernova"] = "À Dakar le soir de la Supernova, elle court sur la plage et ressent une énergie inhabituelle dans les jambes.";
            d["lore.fatou_diallo.story"] = "Athlète de haut niveau en sprint, elle subit un accident grave un an après la Supernova, qui met fin à sa carrière. Pendant sa rééducation, ses muscles produisent une énergie qu'elle n'arrive pas à contrôler. Lors d'un attentat dans le métro parisien, la peur la submerge, et l'énergie prend la forme d'un bouclier lumineux qui protège les voyageurs.";
            d["lore.fatou_diallo.look"] = "Silhouette athlétique, cheveux tressés courts. Tenue moulante blanc et vert sport, avec des bandes lumineuses qui suivent ses mouvements.";
            d["lore.fatou_diallo.power"] = "Transforme son énergie cinétique en projectiles, boucliers et barrières.";
            d["lore.clement_lefevre.age"] = "35 ans";
            d["lore.clement_lefevre.sex"] = "Homme";
            d["lore.clement_lefevre.origin"] = "Nantes, France → Paris";
            d["lore.clement_lefevre.supernova"] = "À Nantes le soir de la Supernova, une foule entière voit le ciel s'embraser alors que le ciel reste normal.";
            d["lore.clement_lefevre.story"] = "Magicien de rue, il trompe les passants pour gagner sa vie. Un soir, quelques mois après la Supernova, sur les quais de la Seine, un de ses tours tourne mal : une foule entière voit un monstre là où il n'y en a pas, et la panique devient réelle. Il comprend que ses illusions peuvent devenir la réalité des autres. [Relocalisé : événement déplacé de Nantes à Paris]";
            d["lore.clement_lefevre.look"] = "Costume de scène noir et rouge à motifs de cartes, chapeau haut-de-forme. Cheveux bruns, sourire en coin. Tenue de héros qui semble changer selon l'angle.";
            d["lore.clement_lefevre.power"] = "Crée des illusions visuelles et sonores qui trompent les sens de ses cibles.";
            d["lore.youssef_haddad.age"] = "32 ans";
            d["lore.youssef_haddad.sex"] = "Homme";
            d["lore.youssef_haddad.origin"] = "Beyrouth, Liban → Paris";
            d["lore.youssef_haddad.supernova"] = "À Beyrouth le soir de la Supernova, il entend un bourdonnement qui ne s'arrête plus pendant trois jours.";
            d["lore.youssef_haddad.story"] = "Ancien enquêteur de la police, il devient aveugle après une explosion, un an après la Supernova. Dans l'obscurité, ses autres sens s'aiguisent au point de voir les vibrations de l'air et d'entendre les battements de cœur à travers les murs. Lors d'une prise d'otages à Paris, il localise chaque otage par l'ouïe, au moment où la panique le submerge.";
            d["lore.youssef_haddad.look"] = "Lunettes de protection à verres teintés, cicatrice en dessous. Tenue de héros bleu nuit avec des capteurs fins sur les tempes, et des oreillettes qui s'illuminent.";
            d["lore.youssef_haddad.power"] = "Décuple ses sens (vue, ouïe, odorat, toucher et « sixième sens »).";
            d["lore.marco_bellini.age"] = "44 ans";
            d["lore.marco_bellini.sex"] = "Homme";
            d["lore.marco_bellini.origin"] = "Florence, Italie → Paris";
            d["lore.marco_bellini.supernova"] = "Dans sa cuisine de Florence le soir de la Supernova, une casserole de plomb devient dorée au contact de sa main.";
            d["lore.marco_bellini.story"] = "Restaurateur passionné, il bouleverse la matière en cuisinant. Un an après la Supernova, il découvre que tout contact de sa main modifie la composition de la matière, après une erreur qui transforme une fois de plus du plomb en or. Lors d'un vol de bijoux à Paris, la peur qu'il ressent face au voleur lui fait transformer les lingots en métal inoffensif.";
            d["lore.marco_bellini.look"] = "Tablier de cuisinier noir et doré, mains marquées de brûlures. Tenue de héros crème et or, avec des motifs alchimiques gravés sur les gants.";
            d["lore.marco_bellini.power"] = "Transforme la composition d'un objet ou d'une matière par simple contact.";
            d["lore.severine_morel.age"] = "39 ans";
            d["lore.severine_morel.sex"] = "Femme";
            d["lore.severine_morel.origin"] = "Toulouse, France → Paris [Relocalisé : de Londres à Paris]";
            d["lore.severine_morel.supernova"] = "À Toulouse le soir de la Supernova, elle se sent vidée de ses forces pendant une garde de nuit.";
            d["lore.severine_morel.story"] = "Infirmière en soins palliatifs, elle se découvre, un an après la Supernova, capable d'aspirer la vitalité de ses patients pour apaiser leurs douleurs. Quand un patient en fin de vie la supplie de le soulager, dans une détresse absolue, elle transfère sa douleur en elle. Le geste est vu par The Dawn, qui l'invite à mettre son pouvoir au service de la protection.";
            d["lore.severine_morel.look"] = "Cheveux roux attachés, teint pâle. Tenue sombre bordeaux et blanche, avec des veines lumineuses qui remontent vers le cou quand elle absorbe l'énergie.";
            d["lore.severine_morel.power"] = "Absorbe l'énergie vitale de ses cibles pour se soigner ou se renforcer.";
            d["lore.ji_hoon_park.age"] = "30 ans";
            d["lore.ji_hoon_park.sex"] = "Homme";
            d["lore.ji_hoon_park.origin"] = "Séoul, Corée du Sud → Paris";
            d["lore.ji_hoon_park.supernova"] = "À Séoul le soir de la Supernova, il croit voir son reflet disparaître de la vitre du métro.";
            d["lore.ji_hoon_park.story"] = "Garçon de bureau dans un grand hôtel parisien, il passe ses journées à être ignoré. Deux ans après la Supernova, un cambriolage est en cours dans une suite, et Ji-Hoon se trouve dans la pièce sans être vu. Terrifié à l'idée qu'un client soit blessé, il réalise que son corps ne se reflète plus, et il sauve les clients sans être repéré.";
            d["lore.ji_hoon_park.look"] = "Costume de groom noir et blanc, cheveux bien coiffés. Tenue de héros noire et grise avec un contour qui scintille quand il devient invisible.";
            d["lore.ji_hoon_park.power"] = "Rend son corps et son équipement invisibles à la vue, sans effacer les sons ni les odeurs.";
            d["lore.darius_brooks.age"] = "41 ans";
            d["lore.darius_brooks.sex"] = "Homme";
            d["lore.darius_brooks.origin"] = "Détroit, États-Unis → New York";
            d["lore.darius_brooks.supernova"] = "À Détroit, il sent un courant électrique dans ses mains au moment de la Supernova. Il met cela sur le compte de la fatigue.";
            d["lore.darius_brooks.story"] = "Mécanicien dans une usine automobile fermée, il répare des machines à la main pour survivre. Quelques mois après la Supernova, il perd son fils dans l'effondrement d'un échafaudage à New York. Dans le désespoir, les poutres se mettent à bouger sous ses ordres et il parvient à en dégager un enfant. Son pouvoir se révèle dans cette seconde de panique absolue.";
            d["lore.darius_brooks.look"] = "Costaud, barbe grisonnante, bras tatoués de rouages. Tenue de travail renforcée avec des plaques de métal articulées, qui bougent légèrement comme des mécanismes.";
            d["lore.darius_brooks.power"] = "Anime et contrôle les objets non organiques : métal, pierre, bois, mobilier.";
            d["lore.mei_lin_chen.age"] = "23 ans";
            d["lore.mei_lin_chen.sex"] = "Femme";
            d["lore.mei_lin_chen.origin"] = "Hong Kong → New York [Relocalisé : de Los Angeles à New York]";
            d["lore.mei_lin_chen.supernova"] = "À Hong Kong, elle se réveille en pleine nuit, la peau brûlante, sans fièvre.";
            d["lore.mei_lin_chen.story"] = "Étudiante en art, elle peint dans un petit atelier. Un an après la Supernova, un incendie détruit l'atelier et sa famille. Elle survit, enfermée dans les flammes, sans brûlure. Plus tard, en colère, alors qu'un gang incendie son quartier à New York, elle sent le feu répondre à sa voix pour la première fois.";
            d["lore.mei_lin_chen.look"] = "Cheveux courts teints en cuivre, mèches orangées. Tenue ignifugée rouge sombre avec des bandes noires, gants longs et un foulard de cendre.";
            d["lore.mei_lin_chen.power"] = "Crée, dirige et étouffe les flammes.";
            d["lore.kwame_abara.age"] = "26 ans";
            d["lore.kwame_abara.sex"] = "Homme";
            d["lore.kwame_abara.origin"] = "Accra, Ghana → New York [Relocalisé : l'événement déclencheur a lieu à New York]";
            d["lore.kwame_abara.supernova"] = "Dans la savane près d'Accra le soir de la Supernova, les animaux du parc deviennent agités pendant toute la nuit.";
            d["lore.kwame_abara.story"] = "Garde-forestier fils de pêcheur, il grandit entouré d'animaux sauvages. Un an après la Supernova, il est engagé comme soigneur au zoo du Bronx. Un trafiquant d'animaux lui tire dessus dans le parc. Sous le choc et la douleur, son corps se transforme, il ressort des fourrés avec des griffes et une crinière, et le trafiquant fuit terrifié. Il découvre alors qu'il peut prendre la forme de n'importe quel animal.";
            d["lore.kwame_abara.look"] = "Torse musclé, peau marquée de tatouages tribaux. Tenue de combat en cuir souple, avec un collier de griffes et des traits qui peuvent devenir félins par moments.";
            d["lore.kwame_abara.power"] = "Se transforme partiellement ou totalement en animal (crocodile, lion, rapace, etc.).";
            d["lore.noah_kaplan.age"] = "45 ans";
            d["lore.noah_kaplan.sex"] = "Homme";
            d["lore.noah_kaplan.origin"] = "Tel-Aviv, Israël → New York [Relocalisé : de Los Angeles à New York]";
            d["lore.noah_kaplan.supernova"] = "Sur un tournage à Tel-Aviv le soir de la Supernova, il croit voir la scène se dédoubler.";
            d["lore.noah_kaplan.story"] = "Ancien cascadeur, il perd un ami sur un tournage quand celui-ci disparaît dans une explosion, bien après la Supernova. Quelques mois plus tard, le même ami réapparaît à l'autre bout de New York, vivant et sans souvenirs. Noah est saisi par la peur et la culpabilité, et il découvre qu'il peut échanger sa position avec un objet ou une personne à portée de vue.";
            d["lore.noah_kaplan.look"] = "Barbe poivre et sel, regard fatigué. Tenue de cascadeur noire aux protections souples, avec une veste reliée par des sangles.";
            d["lore.noah_kaplan.power"] = "Échange sa position avec un objet ou une personne à portée de vue.";
            d["lore.freya_lindqvist.age"] = "22 ans";
            d["lore.freya_lindqvist.sex"] = "Femme";
            d["lore.freya_lindqvist.origin"] = "Stockholm, Suède → New York";
            d["lore.freya_lindqvist.supernova"] = "À Stockholm le soir de la Supernova, elle entend pour la première fois une voix qui n'est pas la sienne, puis le silence revient.";
            d["lore.freya_lindqvist.story"] = "Enfant muette à cause d'un traumatisme, elle communique par gestes. Deux ans après la Supernova, dans une dispute violente avec sa mère, elle entend ses pensées pour la première fois. Elle commence alors à entendre tout le monde, et ce qu'elle entend la terrifie. Lors d'un attentat dans le métro new-yorkais, elle perçoit les pensées de tous les passagers et guide leur évacuation.";
            d["lore.freya_lindqvist.look"] = "Cheveux blancs très clairs, yeux pâles. Tenue fluide gris perle, avec un bandeau et de fines lignes argentées sur les tempes.";
            d["lore.freya_lindqvist.power"] = "Lit et transmet les pensées, communique à distance par la pensée.";
            d["lore.giulia_rossi.age"] = "30 ans";
            d["lore.giulia_rossi.sex"] = "Femme";
            d["lore.giulia_rossi.origin"] = "Naples, Italie → New York [Relocalisé : de Los Angeles à New York]";
            d["lore.giulia_rossi.supernova"] = "À Naples le soir de la Supernova, des objets se mettent à tomber des étagères de sa cuisine.";
            d["lore.giulia_rossi.story"] = "Petite fille dans une famille pauvre, elle fait voler des objets quand elle est en colère, ce qui la fait renvoyer de plusieurs écoles. Adulte, elle travaille dans un casino de Manhattan. Un an après la Supernova, une attaque à main armée la fait trembler de peur. Elle soulève les armes des agresseurs et les projette contre eux. Elle a sauvé des vies, mais elle a aussi appris à se méfier de ses émotions.";
            d["lore.giulia_rossi.look"] = "Cheveux bruns longs et ondulés, maquillage marqué. Tenue rouge bordeaux avec des éclats de cristal sur les épaules, et des bracelets qui tintent lorsqu'elle soulève des objets.";
            d["lore.giulia_rossi.power"] = "Déplace, soulève et projette des objets par la pensée.";
            d["lore.tunde_oyelaran.age"] = "29 ans";
            d["lore.tunde_oyelaran.sex"] = "Homme";
            d["lore.tunde_oyelaran.origin"] = "Ibadan, Nigeria → New York";
            d["lore.tunde_oyelaran.supernova"] = "À Ibadan le soir de la Supernova, il dessine un plan qui se replie tout seul sur sa table.";
            d["lore.tunde_oyelaran.story"] = "Architecte, il conçoit des bâtiments qui s'étendent plus qu'ils ne le devraient. Un an après la Supernova, pendant un chantier à New York, un ouvrier tombe dans un espace qui n'existe pas sur les plans. Pris de panique, Tunde crée un espace parallèle et y cache l'ouvrier juste avant que le bâtiment ne s'effondre.";
            d["lore.tunde_oyelaran.look"] = "Lunettes de dessin rondes, cheveux courts. Tenue de héros gris ardoise avec des motifs de plans géométriques, et des contours qui semblent se replier comme du papier origami.";
            d["lore.tunde_oyelaran.power"] = "Crée des espaces dimensionnels temporaires ou permanents pour stocker, cacher ou piéger.";
            d["lore.lucas_mendes.age"] = "26 ans";
            d["lore.lucas_mendes.sex"] = "Homme";
            d["lore.lucas_mendes.origin"] = "Recife, Brésil → New York [Relocalisé : de Los Angeles à New York]";
            d["lore.lucas_mendes.supernova"] = "Sur une plage de Recife le soir de la Supernova, il sent le sable passer à travers ses pieds.";
            d["lore.lucas_mendes.story"] = "Cascadeur sur des tournages de films d'action, il chute d'un immeuble en plein tournage, un an après la Supernova, et traverse le sol comme s'il n'était pas là. Il survit sans une blessure. Plus tard, pendant une course-poursuite à New York, la peur de voir une otage enfermée le pousse à traverser un camion et des murs pour la sauver.";
            d["lore.lucas_mendes.look"] = "Silhouette athlétique, cheveux bouclés. Tenue légère bleue et grise, avec un contour translucide qui pâlit quand il devient intangible.";
            d["lore.lucas_mendes.power"] = "Rend son corps traversable par la matière, sans pouvoir frapper ni être frappé.";
            d["lore.rin_takeda.age"] = "21 ans";
            d["lore.rin_takeda.sex"] = "Femme";
            d["lore.rin_takeda.origin"] = "Tokyo, Japon → New York";
            d["lore.rin_takeda.supernova"] = "À Tokyo le soir de la Supernova, toutes les radios de son appartement grésillent en même temps.";
            d["lore.rin_takeda.story"] = "Radioamateur et hackeuse, elle capte des signaux que personne d'autre ne perçoit. Deux ans après la Supernova, une transmission qu'elle ne peut pas écouter s'imprime dans son cerveau. Lors d'une panne électrique à New York, un hôpital se retrouve sans courant. Dans la panique, elle rétablit le courant par la seule force de son esprit.";
            d["lore.rin_takeda.look"] = "Cheveux noirs à mèches bleues, casque de radio sur le cou. Tenue de héros bleu électrique et noir, avec des antennes lumineuses sur les épaules.";
            d["lore.rin_takeda.power"] = "Émet, capte, brouille et manipule les ondes électromagnétiques (radio, Wi-Fi, électricité).";
            d["lore.amara_hughes.age"] = "33 ans";
            d["lore.amara_hughes.sex"] = "Femme";
            d["lore.amara_hughes.origin"] = "Atlanta, États-Unis → New York";
            d["lore.amara_hughes.supernova"] = "À Atlanta le soir de la Supernova, elle chante seule dans son église et sent les voix des fidèles à des kilomètres.";
            d["lore.amara_hughes.story"] = "Chanteuse de gospel et thérapeute, elle sent les émotions des gens comme des vibrations. Un an après la Supernova, lors d'un concert en plein air à New York, une foule en colère s'apprête à se battre. Sous le choc de la menace, elle chante, et les émotions de tous s'accordent sur une seule note d'apaisement. The Dawn découvre alors son pouvoir.";
            d["lore.amara_hughes.look"] = "Cheveux naturels volumineux, bijoux dorés. Tenue de héros blanc crème et or, avec des ondes lumineuses qui rayonnent des mains et de la gorge quand elle chante.";
            d["lore.amara_hughes.power"] = "Perçoit et influence les émotions des foules ou des individus, pour apaiser, exciter ou concentrer.";
            d["lore.sam_okafor.age"] = "34 ans";
            d["lore.sam_okafor.sex"] = "Homme";
            d["lore.sam_okafor.origin"] = "Lagos, Nigeria → Moscou [Relocalisé : de Londres à Moscou]";
            d["lore.sam_okafor.supernova"] = "À Moscou le soir de la Supernova, il ressent une douleur fulgurante dans tout le corps, sans conséquence visible.";
            d["lore.sam_okafor.story"] = "Ancien boxeur professionnel, il quitte le ring après une carrière brisée par les coups. Des mois plus tard, une fusillade dans un bar moscovite lui fait encaisser des balles pour protéger sa petite sœur. Il survit sans une blessure. Au milieu du choc, la douleur se transforme en force, et son pouvoir se réveille.";
            d["lore.sam_okafor.look"] = "Carrure massive, cicatrices de boxe sur les arcades. Tenue de héros sombre aux plaques de blindage facettées anthracite, avec des marques dorées qui s'illuminent quand il absorbe un choc. Gants renforcés.";
            d["lore.sam_okafor.power"] = "Absorbe les coups et l'énergie cinétique, puis la redistribue en une onde de choc ou un surcroît de force.";
            d["lore.astrid_hallstrom.age"] = "31 ans";
            d["lore.astrid_hallstrom.sex"] = "Femme";
            d["lore.astrid_hallstrom.origin"] = "Bergen, Norvège → Moscou";
            d["lore.astrid_hallstrom.supernova"] = "En mer au large de Bergen le soir de la Supernova, elle voit l'eau trembler sans raison apparente.";
            d["lore.astrid_hallstrom.story"] = "Pêcheuse, elle perd son bateau dans une tempête un an après la Supernova. Noyée pendant plusieurs minutes, elle reprend conscience sur la plage sans respirer, et l'eau s'est écartée autour d'elle. Ce n'est pourtant pas ce choc qui active son pouvoir. Plus tard, lors d'un naufrage sur la Moskova, à Moscou, elle voit son équipage couler et hurle. C'est la vague qui répond à sa peur et les sauve.";
            d["lore.astrid_hallstrom.look"] = "Cheveux blonds platine tressés, peau claire marquée par le sel. Tenue bleu nuit avec des plaques en écailles translucides, et une cape qui ondule comme une vague.";
            d["lore.astrid_hallstrom.power"] = "Manipule l'eau sous toutes ses formes, de la pluie à la vapeur.";
            d["lore.celeste_moreau.age"] = "38 ans";
            d["lore.celeste_moreau.sex"] = "Femme";
            d["lore.celeste_moreau.origin"] = "Marseille, France → Moscou [Relocalisé : de Londres à Moscou]";
            d["lore.celeste_moreau.supernova"] = "À Marseille, elle ressent le soir de la Supernova une nausée qui dure quelques heures.";
            d["lore.celeste_moreau.story"] = "Chimiste dans un laboratoire pharmaceutique, elle se met à expérimenter des synthèses qui la font rire et voir des couleurs nouvelles. Quelques mois après la Supernova, une explosion de canalisation piège des passagers dans le métro moscovite. Paniquée, elle libère un gaz qui endort les flammes et les survivants. Son pouvoir se révèle à cet instant précis.";
            d["lore.celeste_moreau.look"] = "Cheveux noirs coiffés en chignon, lèvres rouges. Tenue longue violet foncé avec un masque respiratoire argenté et des fioles accrochées à la ceinture.";
            d["lore.celeste_moreau.power"] = "Produit et répand des gaz aux effets variés : toxiques, anesthésiants ou euphorisants.";
            d["lore.anna_petrov.age"] = "24 ans";
            d["lore.anna_petrov.sex"] = "Femme";
            d["lore.anna_petrov.origin"] = "Saint-Pétersbourg, Russie → Moscou";
            d["lore.anna_petrov.supernova"] = "Ballerine au Bolchoï, elle perd connaissance pendant une répétition le soir de la Supernova.";
            d["lore.anna_petrov.story"] = "Jeune ballerine dans le corps de ballet du Bolchoï, elle se blesse gravement lors d'une chute, un an après la Supernova. Pendant son coma, elle fait une série de sauts instantanés vers des endroits qu'elle a vus en rêve. Au réveil, sous une fusillade à Moscou, elle se téléporte une première fois pour sauver un collègue, au moment où la peur la submerge.";
            d["lore.anna_petrov.look"] = "Silhouette gracieuse, cheveux blonds attachés, teint pâle. Tenue ajustée blanc cassé avec des liserés dorés qui laissent une traînée lumineuse quand elle se déplace.";
            d["lore.anna_petrov.power"] = "Se téléporte sur de courtes et moyennes distances, vers des points qu'elle connaît.";
            d["lore.haruto_nakamura.age"] = "19 ans";
            d["lore.haruto_nakamura.sex"] = "Homme";
            d["lore.haruto_nakamura.origin"] = "Osaka, Japon → Moscou [Relocalisé : de Londres à Moscou]";
            d["lore.haruto_nakamura.supernova"] = "À Osaka le soir de la Supernova, il se sent flotter une seconde dans son lit avant de revenir.";
            d["lore.haruto_nakamura.story"] = "Étudiant en médecine, il ne retient de l'après-Supernova qu'une fatigue inexpliquée. Un an plus tard, il fait une crise cardiaque et reste plusieurs minutes en arrêt. Quand il revient, il se souvient d'avoir flotté au-dessus de son corps. Lors d'un incendie dans un hôpital moscovite, il explore les étages sans son corps pour trouver les survivants, et sa peur le détache complètement de sa chair.";
            d["lore.haruto_nakamura.look"] = "Silhouette mince, cheveux noirs mi-longs. Tenue bleu nuit aux motifs d'étoiles pâles, avec une aura bleutée qui se dégage de ses épaules quand il projette son esprit.";
            d["lore.haruto_nakamura.power"] = "Sépare son esprit de son corps pour explorer, espionner ou agir à distance.";
            d["lore.eero_nieminen.age"] = "37 ans";
            d["lore.eero_nieminen.sex"] = "Homme";
            d["lore.eero_nieminen.origin"] = "Helsinki, Finlande → Moscou";
            d["lore.eero_nieminen.supernova"] = "Dans son laboratoire à Helsinki le soir de la Supernova, les lampes se mettent à flotter quelques secondes.";
            d["lore.eero_nieminen.story"] = "Physicien spécialisé dans les champs de force, il participe à une expérience dans un centre de recherche russe, deux ans après la Supernova. La machine perd le contrôle, la gravité se distord autour de lui et du bâtiment. Il survit, et découvre qu'il peut alléger ou alourdir ce qui l'entoure. Il l'utilise pour arrêter une chute de plusieurs étages, dans la panique de l'accident.";
            d["lore.eero_nieminen.look"] = "Barbe courte, regard concentré, cheveux blonds. Tenue grise avec une ceinture à anneaux métalliques en orbite autour de la taille, qui flottent légèrement.";
            d["lore.eero_nieminen.power"] = "Augmente ou diminue localement la gravité, pour écraser ses cibles ou se déplacer dans les airs.";
            d["lore.mateo_vasquez.age"] = "40 ans";
            d["lore.mateo_vasquez.sex"] = "Homme";
            d["lore.mateo_vasquez.origin"] = "Mexico, Mexique → Moscou [Relocalisé : de Los Angeles à Moscou]";
            d["lore.mateo_vasquez.supernova"] = "Aux urgences de Mexico le soir de la Supernova, une dizaine de patients saignent sans raison apparente.";
            d["lore.mateo_vasquez.story"] = "Médecin des urgences, il soigne des victimes de cartels, puis rejoint un hôpital moscovite. Deux ans après la Supernova, un blessé meurt sur la table, et Mateo sent son sang refuser de s'arrêter. Pris de panique à l'idée de perdre un autre patient, il ralentit l'hémorragie d'un policier mourant par la seule force de sa volonté.";
            d["lore.mateo_vasquez.look"] = "Blouse médicale blanche tachée d'un rouge sombre, barbe soignée. Tenue de héros rouge sang et crème, avec des veines lumineuses qui pulsent sur les avant-bras.";
            d["lore.mateo_vasquez.power"] = "Contrôle le sang de ses cibles ou du sien : arrêter une hémorragie, provoquer une coagulation, ou faire saigner.";
            d["lore.zofia_kowalczyk.age"] = "25 ans";
            d["lore.zofia_kowalczyk.sex"] = "Femme";
            d["lore.zofia_kowalczyk.origin"] = "Cracovie, Pologne → Moscou";
            d["lore.zofia_kowalczyk.supernova"] = "Au conservatoire de Cracovie le soir de la Supernova, un accord de violoncelle se prolonge sans fin dans la salle vide.";
            d["lore.zofia_kowalczyk.story"] = "Violoncelliste au conservatoire de Moscou, elle joue lors d'une cérémonie quand, un an après la Supernova, un attentat fait exploser le hall. Dans la panique, son archet vibre, et le son devient une onde qui repousse les décombres et sauve la foule. Depuis, la musique lui obéit.";
            d["lore.zofia_kowalczyk.look"] = "Cheveux roux relevés, robe de scène noire déchirée. Tenue de héros violet et argent, avec un archet monté sur le côté de la ceinture qui vibre quand elle l'utilise.";
            d["lore.zofia_kowalczyk.power"] = "Crée, amplifie, déforme ou annule les sons. Peut produire des ondes destructrices.";
            d["lore.odile_ferrand.age"] = "52 ans";
            d["lore.odile_ferrand.sex"] = "Femme";
            d["lore.odile_ferrand.origin"] = "Genève, Suisse → Moscou [Relocalisé : de Londres à Moscou]";
            d["lore.odile_ferrand.supernova"] = "À Genève le soir de la Supernova, toutes ses montres s'arrêtent une seconde avant de repartir.";
            d["lore.odile_ferrand.story"] = "Horlogère de précision, elle dirige un atelier de haute horlogerie. Deux ans après la Supernova, elle assiste impuissante à un accident de la route dans son champ de vision, sans pouvoir le prévenir. Le temps semble alors ralentir autour d'elle, et elle comprend que son pouvoir est lié à la peur de perdre le temps.";
            d["lore.odile_ferrand.look"] = "Cheveux gris tirés en arrière, lunettes de loupe. Tenue de héros bordeaux et laiton, avec des engrenages apparents sur les épaules et un chronomètre au poignet.";
            d["lore.odile_ferrand.power"] = "Ralentit ou accélère le temps dans une zone limitée autour d'elle.";
            d["lore.yelena_ivanova.age"] = "36 ans";
            d["lore.yelena_ivanova.sex"] = "Femme";
            d["lore.yelena_ivanova.origin"] = "Iakoutsk, Russie → Moscou";
            d["lore.yelena_ivanova.supernova"] = "À Iakoutsk le soir de la Supernova, la température chute brutalement sous le zéro, sans raison.";
            d["lore.yelena_ivanova.story"] = "Née dans l'une des régions les plus froides du monde, elle travaille comme scientifique sur les glaciers. Deux ans après la Supernova, un accident de cryogénisation la laisse entourée de givre. Lors d'une émeute à Moscou, la violence la terrifie, et elle gèle la rue entière pour arrêter les émeutiers.";
            d["lore.yelena_ivanova.look"] = "Cheveux blonds platine, longs, peau très pâle. Tenue de héros bleu glacier et blanc, avec des cristaux de glace sur les épaules et une traîne de givre.";
            d["lore.yelena_ivanova.power"] = "Crée et contrôle la glace et le froid intense : gel, cristaux, barrières.";
        }
    }
}
